temps = [18, 21, 19, 25]
for i in range(len(temps) - 1):
    if temps[i + 1] > temps[i]:
        print('rise at', i + 1)
# rise at 1 / rise at 3
temps[i + 1] needs i to stop at len - 2, so the range ends at len - 1.

votes = ['yes', 'no']
if 'maybe' in votes:
    print(votes.index('maybe'))
else:
    print('not found')
Unlike str.find, list.index has no -1 result; it raises ValueError.

nums = [1, 2, 2, 3]
for n in nums:
    if n == 2:
        nums.remove(n)
print(nums)  # [1, 2, 3]
Removing shifts later items left, so the loop jumps over the second 2.

results = [('Ana', 91), ('Bo', 78), ('Cy', 85)]
for r in results:
    if r[1] >= 80:
        print(r[0])
# Ana / Cy
Each r is one whole tuple.

nums = [1, 2, 2, 3]
for n in nums[:]:
    if n == 2:
        nums.remove(n)
print(nums)  # [1, 3]
The loop walks the unchanging copy, so nothing is skipped.
